require 'fileutils'
require 'open3'
require 'shellwords'

module CBin
  # Builds a component into an iOS XCFramework (device + simulator slices).
  #
  # The project generated by cocoapods-generate already contains a framework
  # target for the component, so Xcode produces complete frameworks (headers,
  # module maps and Swift interfaces); this class only drives xcodebuild,
  # merges the slices and packages the ZIP uploaded to binary-server.
  class XCFrameworkBuilder
    SDKS = %w[iphoneos iphonesimulator].freeze

    attr_reader :spec, :work_dir, :output_dir, :configuration

    def initialize(spec, work_dir:, output_dir:, configuration: 'Release', runner: nil)
      @spec = spec
      @work_dir = Pathname.new(work_dir)
      @output_dir = Pathname.new(output_dir)
      @configuration = configuration
      @runner = runner || method(:run!)
    end

    def self.zip_name(spec)
      "#{spec.name}.xcframework_#{spec.version}.zip"
    end

    def xcframework_name
      "#{spec.name}.xcframework"
    end

    def zip_path
      output_dir + self.class.zip_name(spec)
    end

    # Returns the path of the packaged ZIP.
    def build
      frameworks = SDKS.map { |sdk| build_sdk(sdk) }
      package(frameworks)
    end

    def project_path
      [work_dir + 'Pods.xcodeproj', work_dir + 'Pods/Pods.xcodeproj'].find(&:exist?) ||
        raise(Pod::Informative, "未找到生成的 Pods.xcodeproj: #{work_dir}")
    end

    # Multi-platform specs get a platform suffixed target name, e.g. libwebp-iOS.
    def target_name
      if spec.available_platforms.count > 1
        "#{spec.name}-#{Pod::Platform.string_name(:ios)}"
      else
        spec.name
      end
    end

    def products_dir(sdk)
      work_dir + 'xcframework-build' + sdk
    end

    def xcodebuild_arguments(sdk)
      [
        'xcodebuild', 'build',
        '-project', project_path.to_s,
        '-target', target_name,
        '-configuration', configuration,
        '-sdk', sdk,
        "CONFIGURATION_BUILD_DIR=#{products_dir(sdk)}",
        'BUILD_LIBRARY_FOR_DISTRIBUTION=YES',
        'SKIP_INSTALL=NO',
        'ONLY_ACTIVE_ARCH=NO',
        'CODE_SIGNING_ALLOWED=NO',
        'CODE_SIGNING_REQUIRED=NO'
      ]
    end

    private

    def build_sdk(sdk)
      Pod::UI.message "Building #{spec.name} for #{sdk}"
      FileUtils.rm_rf(products_dir(sdk))
      @runner.call(xcodebuild_arguments(sdk), "#{spec.name} (#{sdk})")
      framework = products_dir(sdk) + "#{spec.module_name || spec.name}.framework"
      framework = products_dir(sdk) + "#{spec.name}.framework" unless framework.exist?
      unless framework.directory?
        raise Pod::Informative, "#{sdk} 编译完成但未生成 framework: #{framework}"
      end
      framework
    end

    def package(frameworks)
      staging = work_dir + 'xcframework-package'
      FileUtils.rm_rf(staging)
      FileUtils.mkdir_p(staging)

      arguments = ['xcodebuild', '-create-xcframework']
      frameworks.each { |framework| arguments += ['-framework', framework.to_s] }
      arguments += ['-output', (staging + xcframework_name).to_s]
      @runner.call(arguments, "#{spec.name} XCFramework")

      copy_resource_bundles(staging)
      copy_license(staging)

      FileUtils.mkdir_p(output_dir)
      FileUtils.rm_f(zip_path)
      # Keep symlinks: macOS framework slices rely on them.
      Dir.chdir(staging) { @runner.call(['zip', '-qry', zip_path.to_s, '.'], "#{spec.name} ZIP") }
      zip_path
    end

    # Static frameworks do not embed resource bundles, so ship them beside the
    # XCFramework; the binary podspec lists them under `resources`.
    def copy_resource_bundles(staging)
      self.class.resource_bundle_names(spec).each do |name|
        bundle = products_dir('iphoneos') + "#{name}.bundle"
        FileUtils.cp_r(bundle, staging) if bundle.exist?
      end
    end

    def copy_license(staging)
      license = spec.license.is_a?(Hash) ? spec.license[:file] : nil
      candidates = [license, 'LICENSE', 'LICENSE.md'].compact
      [work_dir + spec.name, work_dir, Pathname.pwd].each do |dir|
        file = candidates.map { |name| dir + name }.find(&:file?)
        next unless file

        FileUtils.cp(file, staging + 'LICENSE')
        return
      end
    end

    def self.resource_bundle_names(spec)
      [spec, *spec.recursive_subspecs].flat_map do |entry|
        entry.consumer(:ios).resource_bundles.keys
      end.uniq
    end

    def run!(arguments, label)
      output, status = Open3.capture2e(*arguments)
      return output if status.success?

      log = output.lines.last(60).join
      raise Pod::Informative, "#{label} 构建失败: #{Shellwords.join(arguments)}\n#{log}"
    end
  end
end
